## 2. Server Actions with End-to-End Type Safety and Defensive Validation

*Server Actions* execute over an encrypted, strictly typed RPC protocol. When coupled with runtime validation libraries like Zod, they obviate intermediate boilerplate REST endpoints while enforcing strict schema contracts before database persistence:

```typescript
'use server';

import { z } from 'zod';
import { revalidatePath } from 'next/cache';

const UpdateArticleSchema = z.object({
  id: z.number().int().positive(),
  title: z.string().min(5, 'Title must contain at least 5 characters').max(120),
  content: z.string().min(50, 'Content must exceed 50 characters'),
});

export type ActionState = {
  success: boolean;
  error?: string;
};

export async function updateArticleAction(
  prevState: ActionState,
  formData: FormData
): Promise<ActionState> {
  const parseResult = UpdateArticleSchema.safeParse({
    id: Number(formData.get('id')),
    title: formData.get('title'),
    content: formData.get('content'),
  });

  if (!parseResult.success) {
    return {
      success: false,
      error: parseResult.error.errors[0]?.message ?? 'Validation failed',
    };
  }

  // Atomic database mutation (SQLite WAL / TypeORM)
  revalidatePath('/software/news');
  return { success: true };
}
```

